if(f.id==='payday-form'){try{const d=new FormData(f),income=moneyToMinor(d.get('income')),input={income,unpaidEssentials:moneyToMinor(d.get('essentials')),minimums:moneyToMinor(d.get('minimums')),taxes:moneyToMinor(d.get('taxes')),buffer:moneyToMinor(d.get('buffer'))},result=allocateIncome(input);const labels={debt:'Extra credit card payoff',emergency:'Emergency fund',apartment:'Apartment vault',car:'Car vault',travel:'Travel vault',house:'House vault'};const target=$('#payday-result');target.innerHTML=`<div class="money-stats"><div><span>RESERVE FIRST</span><strong>${dollars(result.reserved)}</strong></div><div><span>AVAILABLE FOR GOALS</span><strong>${dollars(result.remaining)}</strong></div><div><span>UNFUNDED COMMITMENTS</span><strong>${dollars(result.shortfall)}</strong></div></div>`+Object.entries(result.allocation).map(([k,v])=>`<div class="category-row"><span>${labels[k]}</span><b>${dollars(v)}</b></div>`).join('')+`<p class="caption">Planning proposal only. No transaction saved or money transferred. Verify available cash and all remaining commitments before spending.</p><button type="button" class="softbutton" id="save-payday">Record this received income ♡</button>`;$('#save-payday').onclick=async()=>{await act(()=>store.put(record('transaction',{title:String(d.get('source'))+' received',date:day(),data:{amount:income,direction:'Income',scope:'Personal',category:d.get('source')==='Studio owner pay'?'Client revenue':'Paycheck'}})),'Income logged. No transfers were made.');};}catch(e){error(e.message);}return;}
if(f.id==='utilization-form'){try{const d=new FormData(f),balance=moneyToMinor(d.get('balance')),limit=moneyToMinor(d.get('limit'));if(!limit)throw Error('Enter a positive credit limit.');$('#utilization-result').textContent=`Current utilization: ${(balance/limit*100).toFixed(1)}%. Pay ${dollars(cardPaydown(balance,limit,.30))} to reach 30%, or ${dollars(cardPaydown(balance,limit,.10))} to reach 10%.`;}catch(e){error(e.message)}return;}
if(f.id==='investment-form'){try{const d=new FormData(f),m=moneyToMinor(d.get('monthly')),years=Number(d.get('years')),rate=Number(d.get('rate'))/100;if(years<1||years>50||rate<0||rate>.15)throw Error('Check the years and annual return.');$('#investment-result').textContent=`Illustrative portfolio: ${dollars(futureValue(m,years,rate))} after ${years} years, including ${dollars(m*years*12)} of your own deposits. Not a forecast.`;}catch(e){error(e.message)}return;}
if(f.id==='scheduler-form'){try{const d=new FormData(f),date=selectedDate||day(),p=scheduleDay(active(store.state),date,{start:String(d.get('start')),end:String(d.get('end')),energy:String(d.get('energy')),buffer:Number(d.get('buffer')),includeWorkout:d.has('workout'),workout:movementForDate(date)});const output=$('#scheduler-preview');output.innerHTML=`<p><strong>${p.blocks.length} suggested blocks</strong> · ${p.appointments.length} existing appointments · ${p.skipped.length} could not fit.</p>`+p.conflicts.map(x=>`<p class="warning">Overlapping appointments: ${esc(x.join(' / '))}</p>`).join('')+p.blocks.map(x=>`<div class="category-row"><span>${hhmm(x.start)}–${hhmm(x.end)} · ${esc(x.title)}</span><span class="tag">${esc(x.kind)}</span></div>`).join('')+`<p class="caption">Review these suggestions. No appointments have been changed.</p><button type="button" class="heart-pill" id="approve-schedule">Save approved blocks to DreamHub ♡</button>`;$('#approve-schedule').onclick=async()=>{const existing=active(store.state).filter(r=>r.type==='event'&&r.date===date&&r.tags?.includes('Day Architect'));const ids=new Set(existing.map(r=>r.data?.sourceId));const pending=p.blocks.filter(x=>!ids.has(x.id));if(!pending.length){error('These blocks have already been saved.');return;}await act(()=>store.update(state=>{for(const x of pending)state.records.push(record('event',{title:x.title,date,tags:['Day Architect',x.kind],links:x.kind==='task'?[x.id]:[],data:{time:hhmm(x.start),endTime:hhmm(x.end),place:'',sourceId:x.id}}));}),'Approved blocks saved to your calendar. ♡');};}catch(e){error(e.message)}return;}
if(f.id==='measurement-form'){try{const d=new FormData(f),data={};for(const k of ['weight','neck','leftArm','rightArm','bust','waist','lowerWaist','hips','leftThigh','rightThigh','leftCalf','rightCalf']){const raw=String(d.get(k)||'').trim();if(raw){const n=Number(raw);if(!Number.isFinite(n)||n<=0||n>1000)throw Error('Check your '+k+' measurement.');data[k]=n;}}if(!Object.keys(data).length&&!String(d.get('notes')||'').trim())throw Error('Enter a measurement or note.');await act(()=>store.put(record('note',{title:'Private progress check-in',date:String(d.get('date')),body:String(d.get('notes')||''),tags:['Private body measurements'],sensitive:true,data})),'Private progress check-in saved. ♡');}catch(e){error(e.message)}return;}
if(f.id==='movement-log-form'){try{const d=new FormData(f),date=selectedDate||day(),result=String(d.get('result')),effort=String(d.get('effort')),session=movementForDate(date),note=String(d.get('notes')||'');await act(()=>store.put(record('habit',{title:session.name,date,body:note,tags:['Movement Garden'],status:result==='complete'?'Done':'Next',data:{rhythm:'Weekly',target:1,logs:[],sessionResult:result,effort,progression:progressionNote(result==='complete',effort)}})),'Movement saved in your garden. ♡');}catch(e){error(e.message)}return;}
if(f.id==='brain-capture-form'){try{const d=new FormData(f),parsed=parseCapture(d.get('thought'));await act(()=>store.put(record('note',{title:parsed.title,body:String(d.get('thought')),date:parsed.date||day(),tags:['Brain capture','Needs sorting']})),'Captured in your Life Inbox. ♡');}catch(e){error(e.message)}return;}
if(f.id==='brain-plan-form'){try{const d=new FormData(f),plan=planDay(active(store.state),selectedDate||day(),d.get('energy'),Number(d.get('minutes')));$('#brain-plan-result').innerHTML=`<p><strong>${plan.appointments.length} appointments</strong> · ${plan.unscheduled} other tasks can wait.</p>`+plan.appointments.map(r=>`<div class="category-row"><span>${esc(r.data.time||'All day')} · ${esc(r.title)}</span></div>`).join('')+plan.blocks.map(b=>`<div class="category-row"><span>${b.kind==='break'?'☕ ': '♡ '}${esc(b.title)}</span><b>${b.minutes} min</b></div>`).join('')+`<p class="caption">${plan.remaining} unassigned minutes. Suggested blocks only; nothing was automatically moved or booked.</p>`;}catch(e){error(e.message)}return;}
if(f.id==='career-prep-form'){try{const d=new FormData(f),application=active(store.state).find(x=>x.id===d.get('application')&&x.type==='application'),prep=interviewPrepLog({application,questions:String(d.get('questions')||''),evidence:String(d.get('evidence')||''),questionsToAsk:String(d.get('questionsToAsk')||''),reflection:String(d.get('reflection')||''),followupDraft:String(d.get('followupDraft')||''),outcome:String(d.get('outcome')||'Preparing'),date:String(d.get('date')||'')});await act(()=>store.put(record('note',{...prep,sensitive:true,tags:[...prep.tags,`Application ${application.id}`]})),'Interview preparation saved and linked to the application ♡');}catch(err){error(err.message)}return;}
if(f.id==='salary-form'){try{const d=new FormData(f),rate=moneyToMinor(d.get('hourly')),hours=Number(d.get('hours')),weeks=Number(d.get('weeks')),annual=Math.round(rate*hours*weeks);$('#salary-result').textContent=`${dollars(annual)} gross per year · ${dollars(Math.round(annual/12))} average gross per month.`;}catch(e){error(e.message)}}
