document.addEventListener('input',e=>{if(e.target.id==='writing-search'){writingQuery=e.target.value;const list=records(route).filter(x=>(route==='journal'?(journalNotebook==='all'||x.data.notebook===journalNotebook):diaryMonth==='all'||x.date.startsWith(diaryMonth))&&`${x.title} ${x.body} ${x.data.prompt||''}`.toLocaleLowerCase().includes(writingQuery.toLocaleLowerCase())).sort((a,b)=>(b.date||'').localeCompare(a.date||''));const out=document.querySelector('.writing-results');if(out)out.innerHTML=list.map(card).join('')||'<p>No writing matches these filters yet.</p>'; }if(e.target.closest('#record-form')&&e.target.type!=='file'){saveDraft();}if(e.target.matches('[data-filter]')){filter=e.target.value;let rs=listFor(route).filter(r=>(tab==='all'||r.type===tab)&&`${r.title} ${r.body} ${r.tags.join(' ')} ${JSON.stringify(r.data)}`.toLowerCase().includes(filter.toLowerCase()));if(route==='tasks'){const pos=e.target.selectionStart;render();const input=$('[data-filter]');input.focus();input.setSelectionRange(pos,pos);}else if($('#record-results'))$('#record-results').innerHTML=rs.length?rs.map(card).join(''):'<p class="calmempty">No pages match yet.</p>';}if(e.target.id==='global-search'){search=e.target.value;const rs=searchRecords(active(store.state),{query:search,...searchFilters,scopeTypes:searchFilters.scope?routeTypes[searchFilters.scope]:null,includePrivateTitles:searchPrivate});$('#search-results').innerHTML=rs.map(r=>r.sensitive?`<article class="recordcard"><span class="tiny-label">PRIVATE ${types[r.type]?.name||'entry'}</span><button class="recordtitle" data-action="edit" data-id="${esc(r.id)}"><h3>${esc(r.title)}</h3></button><p class="caption">Private text and labels concealed</p></article>`:card(r)).join('')||'<p class="calmempty">No pages match. Private content is not searched.</p>';$('#search-count').textContent=rs.length+' matching pages.';}if(e.target.matches('[data-tarot-search]'))document.querySelectorAll('[data-card-name]').forEach(c=>c.hidden=!c.dataset.cardName.includes(e.target.value.toLowerCase()));});
document.addEventListener('change',e=>{if(e.target.matches('[data-inbox-select]')){const id=e.target.dataset.inboxSelect;inboxSelected=e.target.checked?[...new Set([...inboxSelected,id])]:inboxSelected.filter(x=>x!==id);const count=document.querySelectorAll('[data-action="inbox-bulk-state"]');count.forEach(x=>{if(x.dataset.state==='sorted')x.textContent=`Mark selected sorted (${inboxSelected.length})`;});}});
document.addEventListener('change',async e=>{if(e.target.id==='money-month'){month=e.target.value||day().slice(0,7);render();}if(e.target.id==='journal-notebook'){journalNotebook=e.target.value||'all';render();}if(e.target.id==='diary-month'){diaryMonth=e.target.value||'all';render();}if(e.target.id==='focus-task')focusedTask=e.target.value;if(e.target.dataset.room){const room=e.target.dataset.room;await act(()=>store.update(s=>s.settings.hidden=e.target.checked?s.settings.hidden.filter(x=>x!==room):[...new Set([...s.settings.hidden,room])]),'Your rooms are arranged.');}if(e.target.id==='photo-input'&&e.target.files[0]){const file=e.target.files[0];try{if(file.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP picture under 8 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photo=canvas.toDataURL('image/webp',.65);if(photo.length>600000)throw Error('This picture is still too large. Choose a smaller photo.');saveDraft();toast('A little picture added to your draft.');}catch(e){photo='';error(e.message)}}});
$('#backup-input').addEventListener('change',async e=>{const input=e.currentTarget;try{const file=input.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('Choose a backup under 30 MB.');const json=JSON.parse(await file.text());let incoming,warnings=[],encryptedFull=json.format==='dreamhub-vault-backup';if(encryptedFull){const pass=prompt('Enter the passphrase for this encrypted DreamHub backup.');if(pass===null)return;incoming=await decryptMainBackup(json,pass);}else if(json.version===1){const migrated=migrateLegacy(json);incoming=migrated.state;warnings=migrated.warnings;}else incoming=validate(json.state||json);pendingImport=incoming;if(encryptedFull){const accepted=await confirmAction('Restore this full backup?',`${incoming.records.length} records will replace the current workspace, including its preferences, rules, budgets, and history. Export your current data first if you may need it. DreamHub cannot undo this replacement.`,null,'Replace with backup');if(accepted)await act(()=>store.restoreBackup(pendingImport),'Your encrypted backup has been restored. ♡');}else{const plan=previewImport(store.state,incoming),safeName=String(file.name||'Imported backup').replace(/[\u0000-\u001f]/g,'').slice(0,160),conflictList=plan.conflicts.slice(0,8).map(x=>`• ${x.incoming.sensitive?'[Private title hidden]':x.incoming.title} · ${types[x.incoming.type]?.name||x.incoming.type}`).join('\n'),more=plan.conflicts.length>8?`\n…and ${plan.conflicts.length-8} more conflicts.`:'';const detail=`File: ${safeName}\n${plan.added.length} new · ${plan.identical.length} already identical · ${plan.conflicts.length} conflicting IDs.\n${plan.conflicts.length?'Conflict review (current versions will be kept):\n'+conflictList+more:'No conflicting IDs.'}\nOnly new records will be added. Nothing will replace a current record. The import will be recorded in your history and each added record will retain its source. ${warnings.join(' ')}`;const accepted=await confirmAction('Review this import',detail,null,plan.conflicts.length?'Import new pages & keep current versions':'Import new pages');if(accepted)await act(()=>store.import(pendingImport,{conflictPolicy:'keep-existing',sourceLabel:safeName}),'Import reviewed and recorded. New pages were added; current conflicts were kept. ♡');}}catch(err){error('Import stopped: '+err.message)}finally{input.value='';pendingImport=null;}});
$('#editor').addEventListener('cancel',e=>{if(!saveDraft())e.preventDefault();});
window.addEventListener('hashchange',()=>{if($('#editor').open){if(!saveDraft()){location.hash=route;return;}$('#editor').close();}route=location.hash.slice(1)||'home';tab='all';filter='';writingQuery='';mobile=false;rememberPlace(route);render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key===KEY){try{if(store.cloud)return;store.state=store.read();if(!$('#editor').open)render();else toast('Another tab changed your data. Your editor draft stays here; conflicts will be checked on save.');}catch(e){error(e.message)}}});
window.addEventListener('beforeunload',e=>{if($('#editor').open&&!saveDraft()){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#editor').open){if(!saveDraft())return;$('#editor').close();}location.hash='search';requestAnimationFrame(()=>$('#global-search')?.focus());}});
let ticking=false;setInterval(async()=>{const t=store.state.timer;document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=timerText());if(t?.running&&t.endAt<=Date.now()&&!ticking){ticking=true;try{await store.update(s=>{if(!s.timer?.running||s.timer.endAt>Date.now())return;const title=s.records.find(r=>r.id===s.timer.taskId)?.title||'A little focus';s.sessions.push({id:uid(),at:now(),title,minutes:s.timer.duration});s.timer={...s.timer,running:false,remaining:0};});render();toast('Your little focus session is complete. Time for a breath. ♡');}catch(e){error('Session completion could not be saved: '+e.message)}finally{ticking=false;}}},500);
render();
