function careerPrepPanel(){const applications=records('application'),entries=records('note').filter(x=>x.tags.includes('Interview preparation'));return `<section class="panel career-prep"><span class="tiny-label">PREPARE, REFLECT & FOLLOW THROUGH</span><h2>Interview studio</h2>${applications.length?`<form id="career-prep-form" class="formgrid"><label>Application<select name="application" required>${applications.map(x=>`<option value="${esc(x.id)}">${esc(x.data.company||x.title)} · ${esc(x.title)}</option>`).join('')}</select></label><label>Interview date (optional)<input name="date" type="date"></label><label>Current outcome<select name="outcome"><option>Preparing</option><option>Interviewed</option><option>Follow-up sent</option><option>Offer</option><option>No offer</option></select></label><label class="span2">Questions to prepare<textarea name="questions" maxlength="5000" placeholder="Role questions, likely prompts, or questions you want to rehearse"></textarea></label><label class="span2">Evidence and examples<textarea name="evidence" maxlength="5000" placeholder="Projects, outcomes, strengths, and examples from your actual experience"></textarea></label><label class="span2">Questions to ask them<textarea name="questionsToAsk" maxlength="5000" placeholder="Team, expectations, support, schedule, compensation"></textarea></label><label class="span2">Reflection or next steps<textarea name="reflection" maxlength="5000" placeholder="What felt clear? What do you want to learn or follow up on?"></textarea></label><label class="span2">Follow-up draft<textarea name="followupDraft" maxlength="5000" placeholder="A draft stays here for you to review and send yourself"></textarea></label><button class="heart-pill" type="submit">Save interview prep ♡</button></form>`:'<p class="calmempty">Add an application to prepare for an interview.</p>'}<h3>Preparation notes</h3>${entries.length?entries.slice().reverse().map(x=>`<article class="category-row"><div><strong>${esc(x.title)}</strong><small>${esc(x.data.interviewDate||'Date not set')} · ${esc(x.data.outcome||'Preparing')}</small><p>${esc(x.body)}</p><small>Linked application: ${esc(applications.find(a=>a.id===x.data.careerApplicationId)?.title||'Application no longer active')}</small></div></article>`).join(''):'<p class="caption">Your prep notes, examples, reflections, and follow-up drafts will appear here.</p>'}<p class="caption">Marked sensitive and excluded from global search previews by default. Draft follow-ups stay local and are not sent automatically.</p></section>`;}
function pipelinePage(){const career=route==='career',rs=records(career?'application':'client'),columns=career?['Applied','Interview','Offer','Closed']:['Prospect','Conversation','Proposal','In progress','Delivered','Closed'];const stage=r=>career?(columns.includes(r.status)?r.status:'Applied'):(columns.includes(r.data.stage)?r.data.stage:'Prospect');return heading(career?'STABILITY, SKILLS & A FRESH START':'A LITTLE STRUCTURE FOR MY CREATIVE AMBITION',career?'My next <em>beautiful chapter.</em>':'A. Halliwell <em>Studio.</em>',career?'A clear view of applications and possibilities. Your actual experience, your next move.':'Prospects, proposals, delivery. Keep creative work moving at a human pace.',career?'application':'client')+`<div class="pipeline-stats"><div><strong>${rs.length}</strong><span>${career?'applications logged':'studio connections'}</span></div><div><strong>${rs.filter(r=>stage(r)===(career?'Interview':'Proposal')).length}</strong><span>${career?'interviews':'proposals'}</span></div><div><strong>${career?rs.filter(r=>stage(r)==='Offer').length:dollars(rs.filter(r=>['Proposal','In progress'].includes(stage(r))).reduce((s,r)=>s+(r.data.amount||0),0))}</strong><span>${career?'offers':'quoted pipeline · not received cash'}</span></div></div><div class="pipelineboard">${columns.map(col=>`<section class=boardcolumn><div class=boardheading><h2>${col}</h2><span>${rs.filter(r=>stage(r)===col).length}</span></div>${rs.filter(r=>stage(r)===col).map(r=>`<article class=boardcard><span class=tiny-label>${esc(r.data.company||'A new possibility')}</span><button class=recordtitle data-action=edit data-id="${r.id}"><h3>${esc(r.title)}</h3></button><p>${esc(career?r.data.salary||'Compensation not entered':r.data.scope||'A scope worth exploring.')}</p><small>${esc(r.date||'Date not set')}</small><div class=cardactions><button class=textbutton data-action=edit data-id="${r.id}">My next move ↗</button>${safeUrl(r.data.url)?`<a class=iconbutton href="${esc(safeUrl(r.data.url))}" target=_blank rel="noopener noreferrer" aria-label="Open saved website">${icon('arrow')}</a>`:''}</div></article>`).join('')}<button class=boardadd data-action=new data-type="${career?'application':'client'}" data-status="${career?col:'Next'}" data-stage="${col}">${icon('plus')} A new possibility</button></section>`).join('')}</div>${career?`<section class="panel compensation"><span class=tiny-label>KNOW MY NUMBERS</span><h2>A little compensation clarity</h2><form id=salary-form class=inlineform><label>Hourly rate (USD)<input name=hourly inputmode=decimal required></label><label>Hours each week<input name=hours type=number value=40 min=1 max=100 required></label><label>Paid weeks per year<input name=weeks type=number value=52 min=1 max=52 required></label><button class=heart-pill>Compare my income ♡</button></form><div id=salary-result role=status></div><p class=caption>Gross arithmetic only. Taxes, benefits, unpaid time, overtime and actual schedules can change take-home pay.</p></section>${careerPrepPanel()}`:`<section class=panel style="margin-top:25px"><h2>Studio next steps</h2>${records('task').filter(x=>x.tags.includes('Studio')).map(miniTask).join('')||'<p class=calmempty>No next steps yet. A tiny action can start a whole project.</p>'}<button class=softbutton data-action=new data-type=task data-studio=true>Add a studio step ♡</button></section>`}`;}
